MessengerWindow::MessengerWindow(QWidget* p):QMainWindow(p),session_(this){
 setWindowTitle("D-MASH");resize(1080,720);setMinimumSize(720,480);
 setStyleSheet("QMainWindow{background:#f4f7f8;color:#20343d} QWidget{font-family:'Sans Serif';font-size:14px} QPushButton{background:#fff;border:1px solid #d7e2e6;border-radius:7px;padding:8px 14px;color:#26454d} QPushButton:hover{background:#eaf3f3} QPushButton:disabled{color:#9aa9ae;background:#f1f4f5} QPushButton#send{background:#187f83;color:white;border:0;padding:10px 24px} QPushButton#send:disabled{background:#a7c5c6} QTextEdit,QLineEdit,QComboBox{background:white;border:1px solid #dce5e8;border-radius:8px;padding:8px} QListWidget{background:white;border:0;padding:8px} QListWidget::item{padding:15px 10px;border-radius:7px} QListWidget::item:selected{background:#dcefee;color:#145d61} QLabel#wordmark{font-size:23px;font-weight:700;color:#146e73} QLabel#nodeStatus{font-size:11px;color:#667e85} QLabel#chatTitle{font-size:19px;font-weight:600} QLabel#notice{color:#7f5550} QSplitter::handle{background:#e1e8eb;width:1px}");
 auto* central=new QWidget(this);setCentralWidget(central);auto* layout=new QVBoxLayout(central);layout->setContentsMargins(16,14,16,16);layout->setSpacing(10);
 auto* top=new QHBoxLayout;auto* brand=new QLabel("D-MASH");brand->setObjectName("wordmark");top->addWidget(brand);top->addStretch();account_=new QLabel(tr("Your conversations, on your devices"));account_->setTextFormat(Qt::PlainText);top->addWidget(account_);login_=new QPushButton(tr("Sign in"));login_->setObjectName("login");login_->setEnabled(false);logout_=new QPushButton(tr("Sign out"));logout_->setObjectName("logout");logout_->hide();auto* about=new QPushButton(tr("Application details"));about->setObjectName("about");cancel_=new QPushButton(tr("Cancel"));cancel_->setObjectName("cancelWork");cancel_->hide();top->addWidget(login_);top->addWidget(logout_);top->addWidget(cancel_);top->addWidget(about);layout->addLayout(top);
 auto* network=new QHBoxLayout;status_=new QLabel(tr("Node service not attached"));status_->setObjectName("nodeStatus");status_->setTextFormat(Qt::PlainText);status_->setWordWrap(true);network->addWidget(status_,1);refresh_=new QPushButton(tr("Refresh Node status"));refresh_->setObjectName("refresh");refresh_->setEnabled(false);detach_=new QPushButton(tr("Detach UI"));detach_->setObjectName("detach");detach_->setEnabled(false);network->addWidget(refresh_);network->addWidget(detach_);layout->addLayout(network);
 auto* split=new QSplitter;auto* sidebar=new QWidget;auto* side=new QVBoxLayout(sidebar);side->setContentsMargins(0,0,8,0);auto* title=new QLabel(tr("Conversations"));title->setStyleSheet("font-weight:600;padding:8px");side->addWidget(title);chats_=new QListWidget;chats_->setObjectName("chats");chats_->setAccessibleName(tr("Conversations"));chats_->setEnabled(false);side->addWidget(chats_,1);import_=new QPushButton(tr("Import existing profile"));import_->setObjectName("import");import_->setEnabled(false);side->addWidget(import_);split->addWidget(sidebar);
 auto* pane=new QWidget;auto* chat=new QVBoxLayout(pane);chat->setContentsMargins(14,0,0,0);chatTitle_=new QLabel(tr("Welcome to D-MASH"));chatTitle_->setObjectName("chatTitle");chatTitle_->setTextFormat(Qt::PlainText);chat->addWidget(chatTitle_);notice_=new QLabel(tr("Import your existing profile, then sign in to see your conversations."));notice_->setObjectName("notice");notice_->setWordWrap(true);notice_->setTextFormat(Qt::PlainText);chat->addWidget(notice_);history_=new MessageHistory;history_->setObjectName("history");chat->addWidget(history_,1);compose_=new QTextEdit;compose_->setObjectName("compose");compose_->setAccessibleName(tr("Message"));compose_->setPlaceholderText(tr("Write a message…"));compose_->setMaximumHeight(100);compose_->setEnabled(false);chat->addWidget(compose_);auto* actions=new QHBoxLayout;actions->addStretch();send_=new QPushButton(tr("Send"));send_->setObjectName("send");send_->setEnabled(false);actions->addWidget(send_);chat->addLayout(actions);split->addWidget(pane);split->setSizes({280,760});split->setStretchFactor(1,3);layout->addWidget(split,1);
 connect(refresh_,&QPushButton::clicked,&session_,&SessionClient::refresh);connect(detach_,&QPushButton::clicked,&session_,&SessionClient::disconnectSession);
 connect(&session_,&SessionClient::stateChanged,this,[this](const QString& text,bool attached){status_->setText(text);refresh_->setEnabled(attached);detach_->setEnabled(attached);});
 connect(&session_,&SessionClient::nodeStatus,this,[this](const QJsonObject& value){status_->setText(tr("Node %1 · connected peers: %2 · transport %3").arg(value.value("initialized").toBool()?tr("running"):tr("starting")).arg(value.value("connectedPeers").toInt()).arg(value.value("transportEnabled").toBool()?tr("enabled"):tr("paused")));});
 connect(cancel_,&QPushButton::clicked,this,[this]{if(accountOwner_)accountOwner_->cancel();});
 connect(login_,&QPushButton::clicked,this,&MessengerWindow::loginDialog);connect(logout_,&QPushButton::clicked,this,[this]{if(accountOwner_)accountOwner_->logout();});
 connect(import_,&QPushButton::clicked,this,[this]{auto path=QFileDialog::getOpenFileName(this,tr("Import existing D-MASH profile"),{},tr("D-MASH profile (*.json);;All files (*)"));if(path.isEmpty())return;QFile input(path);if(!input.open(QIODevice::ReadOnly)||input.size()>128*1024*1024){notice_->setText(tr("This profile could not be opened."));return;}QJsonParseError error;auto doc=QJsonDocument::fromJson(input.readAll(),&error);if(error.error!=QJsonParseError::NoError||!doc.isObject()){notice_->setText(tr("Choose a complete D-MASH profile export."));return;}importAccountProfile(doc.object());});
 connect(chats_,&QListWidget::currentItemChanged,this,[this](QListWidgetItem* item){if(!item||!accountOwner_)return;peer_=item->data(Qt::UserRole).toString();chatTitle_->setText(item->text());notice_->clear();accountOwner_->history(peer_);updateControls();});
 connect(send_,&QPushButton::clicked,this,[this]{if(accountOwner_&&!peer_.isEmpty()&&!compose_->toPlainText().trimmed().isEmpty())accountOwner_->send(peer_,compose_->toPlainText());});
 connect(compose_,&QTextEdit::textChanged,this,&MessengerWindow::updateControls);
 connect(about,&QPushButton::clicked,this,[this]{QDialog d(this);d.setObjectName("aboutDialog");d.setWindowTitle(tr("About D-MASH"));auto* l=new QVBoxLayout(&d);auto* text=new QLabel(tr("D-MASH native client · development version\nYour Account and encrypted history stay on your device.\nBackground Node transport runs separately.\nSome contact and background features are still in development."));text->setWordWrap(true);l->addWidget(text);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Close);l->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);d.exec();});
}
void MessengerWindow::openAccountProfile(const QString& path){
 try{accountOwner_=std::make_unique<AccountController>(path,this);}catch(const std::exception& error){notice_->setText(tr("This profile needs recovery (%1). Its data was kept.").arg(QString::fromUtf8(error.what())));return;}
 connect(accountOwner_.get(),&AccountController::busyChanged,this,[this](bool busy){working_=busy;if(busy)notice_->setText(tr("Working…"));updateControls();});
 connect(accountOwner_.get(),&AccountController::rootUnlockRequired,this,[this]{needRoot_=true;notice_->setText(tr("Unlock your device to open your Accounts."));updateControls();});
 connect(accountOwner_.get(),&AccountController::accountsReady,this,[this](const QJsonArray& rows){accounts_=rows;needRoot_=false;notice_->setText(rows.isEmpty()?tr("Import your existing profile to continue."):tr("Sign in to open your conversations."));updateControls();});
 connect(accountOwner_.get(),&AccountController::signedIn,this,[this](const QJsonObject& v){loggedIn_=true;account_->setText(v.value("displayName").toString(tr("Account")));notice_->clear();updateControls();});
 connect(accountOwner_.get(),&AccountController::signedOut,this,[this]{loggedIn_=false;peer_.clear();chats_->clear();history_->clear();compose_->clear();account_->setText(tr("Signed out"));chatTitle_->setText(tr("Your conversations"));notice_->setText(tr("Sign in to continue. Node transport keeps running independently."));updateControls();});
 connect(accountOwner_.get(),&AccountController::contactsReady,this,[this](const QJsonArray& rows){chats_->clear();for(const auto& value:rows){auto v=value.toObject();auto* item=new QListWidgetItem(v.value("name").toString(v.value("id").toString()),chats_);item->setData(Qt::UserRole,v.value("id").toString());item->setToolTip(v.value("state").toString());}chats_->setEnabled(true);if(chats_->count())chats_->setCurrentRow(0);});
 connect(accountOwner_.get(),&AccountController::historyReady,this,&MessengerWindow::showHistory);
 connect(accountOwner_.get(),&AccountController::sent,this,[this](const QJsonObject& v){if(v.value("accepted").toBool()){compose_->clear();accountOwner_->history(peer_);}else notice_->setText(tr("The message has not been accepted. Please try again."));});
 connect(accountOwner_.get(),&AccountController::failed,this,[this](const QString& code){notice_->setText(code=="ACCOUNT_SESSION_CHANGED"?tr("Action cancelled."):code.contains("PASSWORD")||code.contains("LOGIN")?tr("Could not sign in. Check your Account password."):tr("Could not complete this action (%1). Your stored data was kept.").arg(code));});
 accountOwner_->loadAccounts();updateControls();
}
void MessengerWindow::importAccountProfile(const QJsonObject& v){if(accountOwner_)rootUnlockDialog(v);}
void MessengerWindow::rootUnlockDialog(const QJsonObject& profile){QDialog dialog(this);dialog.setObjectName("rootUnlockDialog");dialog.setWindowTitle(tr("Unlock device"));auto* layout=new QVBoxLayout(&dialog);auto* label=new QLabel(tr("Enter the device PIN for this profile."));layout->addWidget(label);auto* pin=new QLineEdit;pin->setObjectName("rootPin");pin->setEchoMode(QLineEdit::Password);pin->setPlaceholderText(tr("Device PIN"));layout->addWidget(pin);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Ok)->setText(tr("Unlock"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{auto value=pin->text();pin->clear();if(profile.isEmpty())accountOwner_->unlockRoot(value);else accountOwner_->importProfile(profile,value);dialog.accept();});connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.exec();}
void MessengerWindow::updateControls(){cancel_->setVisible(working_);login_->setVisible(!loggedIn_);login_->setText(needRoot_?tr("Unlock device"):tr("Sign in"));login_->setEnabled(accountOwner_&&(needRoot_||!accounts_.isEmpty())&&!working_);logout_->setVisible(loggedIn_);logout_->setEnabled(!working_);import_->setEnabled(accountOwner_&&!loggedIn_&&!working_);chats_->setEnabled(loggedIn_&&!working_);compose_->setEnabled(loggedIn_&&!peer_.isEmpty()&&!working_);send_->setEnabled(compose_->isEnabled()&&!compose_->toPlainText().trimmed().isEmpty());}
void MessengerWindow::loginDialog(){if(needRoot_){rootUnlockDialog();return;}if(!accountOwner_||accounts_.isEmpty())return;QDialog d(this);d.setObjectName("loginDialog");d.setWindowTitle(tr("Sign in"));auto* layout=new QVBoxLayout(&d);auto* accounts=new QComboBox;accounts->setObjectName("accountChoice");for(const auto& value:accounts_){auto v=value.toObject();QString id=v.value("identity").toString(v.value("id").toString());accounts->addItem(v.value("name").toString(v.value("displayName").toString(id)),id);}layout->addWidget(accounts);auto* password=new QLineEdit;password->setObjectName("accountPassword");password->setEchoMode(QLineEdit::Password);password->setPlaceholderText(tr("Account password"));layout->addWidget(password);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Ok)->setText(tr("Sign in"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&d,[&]{auto text=password->text();password->clear();accountOwner_->login(accounts->currentData().toString(),text);d.accept();});connect(buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);d.exec();}
void MessengerWindow::showHistory(const QJsonArray& rows){notice_->clear();history_->setRows(rows);updateControls();}
